; ---------------------------------------------------------------
; void __near__ handle_key_command (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_handle_key_command: near

.segment	"CODE"

	lda     __current_tool
	cmp     #$03
	bne     L000C
	lda     _keycode
	cmp     #$1B
	bne     L000A
	stz     _point_selected
	rts
L000C:	lda     __current_tool
	bne     L000A
	lda     _keycode
	cmp     #$3D
	bne     L000D
	lda     #$02
	clc
	adc     _brush_size
	sta     _brush_size
	cmp     #$11
	bcc     L000A
	lda     #$10
	bra     L000B
L000D:	lda     _keycode
	cmp     #$2D
	bne     L000A
	lda     _brush_size
	sec
	sbc     #$02
	sta     _brush_size
	cmp     #$02
	bcs     L000A
	lda     #$02
L000B:	sta     _brush_size
L000A:	rts

.endproc

